00059 DecAppMem::DecAppMem(VideoIOYuvMem::Writer *writer)
00060     : m_iPOCLastDisplay(-MAX_INT), m_writer(writer)
00061 {
00062   m_reconFileName="memory";
00063 
00064   for (int i = 0; i < MAX_NUM_LAYER_IDS; i++)
00065   {
00066     m_newCLVS[i] = true;
00067   }
00068 }
