00070 // ====================================================================================================================
00071 // Public member functions
00072 // ====================================================================================================================
00073 
00082 uint32_t DecAppMem::decode(std::istream& bitstreamFile)
00083 {
00084   int                 poc;
00085   PicList* pcListPic = NULL;
00086 
00087 
00088   InputByteStream bytestream(bitstreamFile);
00089 
00090   if (!m_outputDecodedSEIMessagesFilename.empty() && m_outputDecodedSEIMessagesFilename!="-")
00091   {
00092     m_seiMessageFileStream.open(m_outputDecodedSEIMessagesFilename.c_str(), std::ios::out);
00093     if (!m_seiMessageFileStream.is_open() || !m_seiMessageFileStream.good())
00094     {
00095       EXIT( "Unable to open file "<< m_outputDecodedSEIMessagesFilename.c_str() << " for writing decoded SEI messages");
00096     }
00097   }
00098 
00099   if (!m_oplFilename.empty() && m_oplFilename!="-")
00100   {
00101     m_oplFileStream.open(m_oplFilename.c_str(), std::ios::out);
00102     if (!m_oplFileStream.is_open() || !m_oplFileStream.good())
00103     {
00104       EXIT( "Unable to open file "<< m_oplFilename.c_str() << " to write an opl-file for conformance testing (see JVET-P2008 for details)");
00105     }
00106   }
00107 
00108   // create & initialize internal classes
00109   xCreateDecLib();
00110 
00111   m_iPOCLastDisplay += m_iSkipFrame;      // set the last displayed POC correctly for skip forward.
00112 
00113   // clear contents of colour-remap-information-SEI output file
00114   if (!m_colourRemapSEIFileName.empty())
00115   {
00116     std::ofstream ofile(m_colourRemapSEIFileName.c_str());
00117     if (!ofile.good() || !ofile.is_open())
00118     {
00119       EXIT( "Unable to open file " << m_colourRemapSEIFileName.c_str() << " for writing colour-remap-information-SEI video");
00120     }
00121   }
00122 
00123   // main decoder loop
00124   bool loopFiltered[MAX_VPS_LAYERS] = { false };
00125 
00126   bool bPicSkipped = false;
00127 
00128   bool isEosPresentInPu = false;
00129 #if JVET_S0078_NOOUTPUTPRIORPICFLAG
00130   bool firstSliceInAU = true;
00131 #endif
00132 
00133   bool outputPicturePresentInBitstream = false;
00134   auto setOutputPicturePresentInStream = [&]()
00135   {
00136     if( !outputPicturePresentInBitstream )
00137     {
00138       PicList::iterator iterPic = pcListPic->begin();
00139       while (!outputPicturePresentInBitstream && iterPic != pcListPic->end())
00140       {
00141         Picture *pcPic = *(iterPic++);
00142         if (pcPic->neededForOutput)
00143         {
00144           outputPicturePresentInBitstream = true;
00145         }
00146       }
00147     }
00148   };
00149 
00150 #if JVET_S0163_ON_TARGETOLS_SUBLAYERS
00151     m_cDecLib.setHTidExternalSetFlag(m_mTidExternalSet);
00152     m_cDecLib.setTOlsIdxExternalFlag(m_tOlsIdxTidExternalSet);
00153 #endif
00154 
00155   while (!!bitstreamFile)
00156   {
00157     InputNALUnit nalu;
00158     nalu.m_nalUnitType = NAL_UNIT_INVALID;
00159 
00160     // determine if next NAL unit will be the first one from a new picture
00161     bool bNewPicture = m_cDecLib.isNewPicture(&bitstreamFile, &bytestream);
00162     bool bNewAccessUnit = bNewPicture && m_cDecLib.isNewAccessUnit( bNewPicture, &bitstreamFile, &bytestream );
00163     if(!bNewPicture)
00164     {
00165       AnnexBStats stats = AnnexBStats();
00166 
00167       // find next NAL unit in stream
00168       byteStreamNALUnit(bytestream, nalu.getBitstream().getFifo(), stats);
00169       if (nalu.getBitstream().getFifo().empty())
00170       {
00171         /* this can happen if the following occur:
00172          *  - empty input file
00173          *  - two back-to-back start_code_prefixes
00174          *  - start_code_prefix immediately followed by EOF
00175          */
00176         msg( ERROR, "Warning: Attempt to decode an empty NAL unit\n");
00177       }
00178       else
00179       {
00180         // read NAL unit header
00181         read(nalu);
00182 
00183         // flush output for first slice of an IDR picture
00184         if(m_cDecLib.getFirstSliceInPicture() &&
00185             (nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_IDR_W_RADL ||
00186              nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_IDR_N_LP))
00187         {
00188           m_newCLVS[nalu.m_nuhLayerId] = true;   // An IDR picture starts a new CLVS
00189 #if !JVET_S0078_NOOUTPUTPRIORPICFLAG
00190           xFlushOutput(pcListPic, nalu.m_nuhLayerId);
00191 #endif
00192         }
00193         if (m_cDecLib.getFirstSliceInPicture() && nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_CRA && isEosPresentInPu)
00194         {
00195           // A CRA that is immediately preceded by an EOS is a CLVSS
00196           m_newCLVS[nalu.m_nuhLayerId] = true;
00197         }
00198         else if (m_cDecLib.getFirstSliceInPicture() && nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_CRA && !isEosPresentInPu)
00199         {
00200           // A CRA that is not immediately precede by an EOS is not a CLVSS
00201           m_newCLVS[nalu.m_nuhLayerId] = false;
00202         }
00203 
00204         // parse NAL unit syntax if within target decoding layer
00205         if( ( m_iMaxTemporalLayer < 0 || nalu.m_temporalId <= m_iMaxTemporalLayer ) && xIsNaluWithinTargetDecLayerIdSet( &nalu ) )
00206         {
00207           CHECK(nalu.m_temporalId > m_iMaxTemporalLayer, "bitstream shall not include any NAL unit with TemporalId greater than HighestTid");
00208           if (m_targetDecLayerIdSet.size())
00209           {
00210             CHECK(std::find(m_targetDecLayerIdSet.begin(), m_targetDecLayerIdSet.end(), nalu.m_nuhLayerId) == m_targetDecLayerIdSet.end(), "bitstream shall not contain any other layers than included in the OLS with OlsIdx");
00211           }
00212           if (bPicSkipped)
00213           {
00214             if ((nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_TRAIL) || (nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_STSA) || (nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_RASL) || (nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_RADL) || (nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_IDR_W_RADL) || (nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_IDR_N_LP) || (nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_CRA) || (nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_GDR))
00215             {
00216               if (m_cDecLib.isSliceNaluFirstInAU(true, nalu))
00217               {
00218                 m_cDecLib.resetAccessUnitNals();
00219                 m_cDecLib.resetAccessUnitApsNals();
00220                 m_cDecLib.resetAccessUnitPicInfo();
00221               }
00222               bPicSkipped = false;
00223             }
00224           }
00225           m_cDecLib.decode(nalu, m_iSkipFrame, m_iPOCLastDisplay, m_targetOlsIdx);
00226 #if JVET_S0163_ON_TARGETOLS_SUBLAYERS
00227           if (nalu.m_nalUnitType == NAL_UNIT_OPI)
00228           {
00229             if (!m_cDecLib.getHTidExternalSetFlag() && m_cDecLib.getOPI()->getHtidInfoPresentFlag())
00230             {
00231               m_iMaxTemporalLayer = m_cDecLib.getOPI()->getOpiHtidPlus1()-1;
00232             }
00233             m_cDecLib.setHTidOpiSetFlag(m_cDecLib.getOPI()->getHtidInfoPresentFlag());
00234           }
00235 #endif
00236           if (nalu.m_nalUnitType == NAL_UNIT_VPS)
00237           {
00238 #if JVET_S0163_ON_TARGETOLS_SUBLAYERS
00239             m_cDecLib.deriveTargetOutputLayerSet( m_cDecLib.getVPS()->m_targetOlsIdx );
00240 #else
00241             m_cDecLib.deriveTargetOutputLayerSet( m_targetOlsIdx );
00242 #endif
00243             m_targetDecLayerIdSet = m_cDecLib.getVPS()->m_targetLayerIdSet;
00244             m_targetOutputLayerIdSet = m_cDecLib.getVPS()->m_targetOutputLayerIdSet;
00245           }
00246         }
00247         else
00248         {
00249           bPicSkipped = true;
00250         }
00251       }
00252       // once an EOS NAL unit appears in the current PU, mark the variable isEosPresentInPu as true
00253       if (nalu.m_nalUnitType == NAL_UNIT_EOS)
00254       {
00255         isEosPresentInPu = true;
00256         m_newCLVS[nalu.m_nuhLayerId] = true;  //The presence of EOS means that the next picture is the beginning of new CLVS
00257       }
00258       // within the current PU, only EOS and EOB are allowed to be sent after an EOS nal unit
00259       if(isEosPresentInPu)
00260       {
00261         CHECK(nalu.m_nalUnitType != NAL_UNIT_EOS && nalu.m_nalUnitType != NAL_UNIT_EOB, "When an EOS NAL unit is present in a PU, it shall be the last NAL unit among all NAL units within the PU other than other EOS NAL units or an EOB NAL unit");
00262       }
00263     }
00264 
00265     if ((bNewPicture || !bitstreamFile || nalu.m_nalUnitType == NAL_UNIT_EOS) && !m_cDecLib.getFirstSliceInSequence(nalu.m_nuhLayerId) && !bPicSkipped)
00266     {
00267       if (!loopFiltered[nalu.m_nuhLayerId] || bitstreamFile)
00268       {
00269         m_cDecLib.executeLoopFilters();
00270         m_cDecLib.finishPicture(poc, pcListPic, INFO, m_newCLVS[nalu.m_nuhLayerId]);
00271       }
00272       loopFiltered[nalu.m_nuhLayerId] = (nalu.m_nalUnitType == NAL_UNIT_EOS);
00273       if (nalu.m_nalUnitType == NAL_UNIT_EOS)
00274       {
00275         m_cDecLib.setFirstSliceInSequence(true, nalu.m_nuhLayerId);
00276       }
00277 
00278       m_cDecLib.updateAssociatedIRAP();
00279       m_cDecLib.updatePrevGDRInSameLayer();
00280       m_cDecLib.updatePrevIRAPAndGDRSubpic();
00281     }
00282     else if ( (bNewPicture || !bitstreamFile || nalu.m_nalUnitType == NAL_UNIT_EOS ) &&
00283       m_cDecLib.getFirstSliceInSequence(nalu.m_nuhLayerId))
00284     {
00285       m_cDecLib.setFirstSliceInPicture (true);
00286     }
00287 
00288     if( pcListPic )
00289     {
00290       if( !m_reconFileName.empty() && !m_cVideoIOYuvReconFile[nalu.m_nuhLayerId].isOpen() )
00291       {
00292         const BitDepths &bitDepths=pcListPic->front()->cs->sps->getBitDepths(); // use bit depths of first reconstructed picture.
00293         for( uint32_t channelType = 0; channelType < MAX_NUM_CHANNEL_TYPE; channelType++ )
00294         {
00295             if( m_outputBitDepth[channelType] == 0 )
00296             {
00297                 m_outputBitDepth[channelType] = bitDepths.recon[channelType];
00298             }
00299         }
00300 
00301         if (m_packedYUVMode && (m_outputBitDepth[CH_L] != 10 && m_outputBitDepth[CH_L] != 12))
00302         {
00303           EXIT ("Invalid output bit-depth for packed YUV output, aborting\n");
00304         }
00305 
00306         std::string reconFileName = m_reconFileName;
00307         if( m_reconFileName.compare( "/dev/null" ) && m_cDecLib.getVPS() != nullptr && m_cDecLib.getVPS()->getMaxLayers() > 1 && xIsNaluWithinTargetOutputLayerIdSet( &nalu ) )
00308         {
00309           size_t pos = reconFileName.find_last_of('.');
00310           std::string layerString = std::string(".layer") + std::to_string(nalu.m_nuhLayerId);
00311           if (pos != string::npos)
00312           {
00313             reconFileName.insert(pos, layerString);
00314           }
00315           else
00316           {
00317             reconFileName.append(layerString);
00318           }
00319         }
00320         if( ( m_cDecLib.getVPS() != nullptr && ( m_cDecLib.getVPS()->getMaxLayers() == 1 || xIsNaluWithinTargetOutputLayerIdSet( &nalu ) ) ) || m_cDecLib.getVPS() == nullptr )
00321         {
00322           m_cVideoIOYuvReconFile[nalu.m_nuhLayerId].open( m_writer, true, m_outputBitDepth, m_outputBitDepth, bitDepths.recon ); // write mode
00323         }
00324       }
00325       // update file bitdepth shift if recon bitdepth changed between sequences
00326       for( uint32_t channelType = 0; channelType < MAX_NUM_CHANNEL_TYPE; channelType++ )
00327       {
00328         int reconBitdepth = pcListPic->front()->cs->sps->getBitDepth((ChannelType)channelType);
00329         int fileBitdepth  = m_cVideoIOYuvReconFile[nalu.m_nuhLayerId].getFileBitdepth(channelType);
00330         int bitdepthShift = m_cVideoIOYuvReconFile[nalu.m_nuhLayerId].getBitdepthShift(channelType);
00331         if( fileBitdepth + bitdepthShift != reconBitdepth )
00332         {
00333           m_cVideoIOYuvReconFile[nalu.m_nuhLayerId].setBitdepthShift(channelType, reconBitdepth - fileBitdepth);
00334         }
00335       }
00336       // write reconstruction to file
00337       if( bNewPicture )
00338       {
00339         setOutputPicturePresentInStream();
00340         xWriteOutput( pcListPic, nalu.m_temporalId );
00341       }
00342       if (nalu.m_nalUnitType == NAL_UNIT_EOS)
00343       {
00344         setOutputPicturePresentInStream();
00345         xWriteOutput( pcListPic, nalu.m_temporalId );
00346         m_cDecLib.setFirstSliceInPicture (false);
00347       }
00348       // write reconstruction to file -- for additional bumping as defined in C.5.2.3
00349 #if JVET_S0163_ON_TARGETOLS_SUBLAYERS
00350       if (!bNewPicture && ((nalu.m_nalUnitType >= NAL_UNIT_CODED_SLICE_TRAIL && nalu.m_nalUnitType <= NAL_UNIT_RESERVED_IRAP_VCL_11)
00351         || (nalu.m_nalUnitType >= NAL_UNIT_CODED_SLICE_IDR_W_RADL && nalu.m_nalUnitType <= NAL_UNIT_CODED_SLICE_GDR)))
00352 #else
00353       if (!bNewPicture && ((nalu.m_nalUnitType >= NAL_UNIT_CODED_SLICE_TRAIL && nalu.m_nalUnitType <= NAL_UNIT_RESERVED_IRAP_VCL_11)
00354         || (nalu.m_nalUnitType >= NAL_UNIT_CODED_SLICE_IDR_W_RADL && nalu.m_nalUnitType <= NAL_UNIT_CODED_SLICE_GDR)))
00355 #endif
00356       {
00357         setOutputPicturePresentInStream();
00358 #if JVET_S0078_NOOUTPUTPRIORPICFLAG
00359         bool firstPicInCVSAUThatIsNotAU0 = false;
00360         if (firstSliceInAU)
00361         {
00362           if (m_targetDecLayerIdSet.size() > 0)
00363           {
00364             if (m_cDecLib.getAudIrapOrGdrAuFlag())
00365             {
00366               firstPicInCVSAUThatIsNotAU0 = true;
00367             }
00368           }
00369           else
00370           {
00371             if (nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_IDR_W_RADL
00372                 || nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_IDR_N_LP
00373                 || (nalu.m_nalUnitType == NAL_UNIT_CODED_SLICE_CRA && isEosPresentInPu))
00374             {
00375               firstPicInCVSAUThatIsNotAU0 = true;
00376             }
00377           }
00378         }
00379         if (firstPicInCVSAUThatIsNotAU0)
00380         {
00381           xFlushOutput(pcListPic, NOT_VALID, m_cDecLib.getNoOutputPriorPicsFlag());
00382         }
00383         else
00384         {
00385           xWriteOutput(pcListPic, nalu.m_temporalId);
00386         }
00387 #else
00388         xWriteOutput( pcListPic, nalu.m_temporalId );
00389 #endif
00390       }
00391     }
00392 #if JVET_S0078_NOOUTPUTPRIORPICFLAG
00393 #if JVET_S0163_ON_TARGETOLS_SUBLAYERS
00394     if ((nalu.m_nalUnitType >= NAL_UNIT_CODED_SLICE_TRAIL && nalu.m_nalUnitType <= NAL_UNIT_OPI)
00395         || (nalu.m_nalUnitType >= NAL_UNIT_CODED_SLICE_IDR_W_RADL && nalu.m_nalUnitType <= NAL_UNIT_CODED_SLICE_GDR))
00396     {
00397       firstSliceInAU = false;
00398     }
00399 #else
00400     if ((nalu.m_nalUnitType >= NAL_UNIT_CODED_SLICE_TRAIL && nalu.m_nalUnitType <= NAL_UNIT_RESERVED_IRAP_VCL_12)
00401         || (nalu.m_nalUnitType >= NAL_UNIT_CODED_SLICE_IDR_W_RADL && nalu.m_nalUnitType <= NAL_UNIT_CODED_SLICE_GDR))
00402     {
00403       firstSliceInAU = false;
00404     }
00405 #endif
00406 #endif
00407     if( bNewPicture )
00408     {
00409       m_cDecLib.checkSeiInPictureUnit();
00410       m_cDecLib.resetPictureSeiNalus();
00411       // reset the EOS present status for the next PU check
00412       isEosPresentInPu = false;
00413     }
00414     if (bNewPicture || !bitstreamFile || nalu.m_nalUnitType == NAL_UNIT_EOS)
00415     {
00416       m_cDecLib.checkAPSInPictureUnit();
00417       m_cDecLib.resetPictureUnitNals();
00418     }
00419     if (bNewAccessUnit || !bitstreamFile)
00420     {
00421       m_cDecLib.CheckNoOutputPriorPicFlagsInAccessUnit();
00422       m_cDecLib.resetAccessUnitNoOutputPriorPicFlags();
00423       m_cDecLib.checkLayerIdIncludedInCvss();
00424       m_cDecLib.resetAccessUnitEos();
00425       m_cDecLib.resetAudIrapOrGdrAuFlag();
00426     }
00427     if(bNewAccessUnit)
00428     {
00429       m_cDecLib.checkTidLayerIdInAccessUnit();
00430       m_cDecLib.resetAccessUnitSeiTids();
00431       m_cDecLib.checkSEIInAccessUnit();
00432       m_cDecLib.resetAccessUnitSeiPayLoadTypes();
00433       m_cDecLib.resetAccessUnitNals();
00434       m_cDecLib.resetAccessUnitApsNals();
00435       m_cDecLib.resetAccessUnitPicInfo();
00436 #if JVET_S0078_NOOUTPUTPRIORPICFLAG
00437       firstSliceInAU = true;
00438 #endif
00439     }
00440   }
00441   // May need to check again one more time as in case one the bitstream has only one picture, the first check may miss it
00442   setOutputPicturePresentInStream();
00443   CHECK(!outputPicturePresentInBitstream, "It is required that there shall be at least one picture with PictureOutputFlag equal to 1 in the bitstream")
00444 
00445   xFlushOutput( pcListPic );
00446 
00447   // get the number of checksum errors
00448   uint32_t nRet = m_cDecLib.getNumberOfChecksumErrorsDetected();
00449 
00450   // delete buffers
00451   m_cDecLib.deletePicBuffer();
00452   // destroy internal classes
00453   xDestroyDecLib();
00454 
00455 #if RExt__DECODER_DEBUG_STATISTICS
00456   CodingStatistics::DestroyInstance();
00457 #endif
00458 
00459   destroyROM();
00460 
00461   return nRet;
00462 }
00463 
00464 
00465 
00466 void DecAppMem::writeLineToOutputLog(Picture * pcPic)
00467 {
00468   if (m_oplFileStream.is_open() && m_oplFileStream.good())
00469   {
00470     const SPS *   sps             = pcPic->cs->sps;
00471     ChromaFormat  chromaFormatIDC = sps->getChromaFormatIdc();
00472     const Window &conf            = pcPic->getConformanceWindow();
00473     const int     leftOffset      = conf.getWindowLeftOffset() * SPS::getWinUnitX(chromaFormatIDC);
00474     const int     rightOffset     = conf.getWindowRightOffset() * SPS::getWinUnitX(chromaFormatIDC);
00475     const int     topOffset       = conf.getWindowTopOffset() * SPS::getWinUnitY(chromaFormatIDC);
00476     const int     bottomOffset    = conf.getWindowBottomOffset() * SPS::getWinUnitY(chromaFormatIDC);
00477     PictureHash   recon_digest;
00478     auto numChar = calcMD5WithCropping(((const Picture *) pcPic)->getRecoBuf(), recon_digest, sps->getBitDepths(),
00479                                        leftOffset, rightOffset, topOffset, bottomOffset);
00480 
00481     const int croppedWidth  = pcPic->Y().width - leftOffset - rightOffset;
00482     const int croppedHeight = pcPic->Y().height - topOffset - bottomOffset;
00483 
00484     m_oplFileStream << std::setw(3) << pcPic->layerId << ",";
00485     m_oplFileStream << std::setw(8) << pcPic->getPOC() << "," << std::setw(5) << croppedWidth << "," << std::setw(5)
00486                     << croppedHeight << "," << hashToString(recon_digest, numChar) << "\n";
00487   }
00488 }
00489 
00490 // ====================================================================================================================
00491 // Protected member functions
00492 // ====================================================================================================================
00493 
00494 void DecAppMem::xCreateDecLib()
00495 {
00496   initROM();
00497 
00498   // create decoder class
00499   m_cDecLib.create();
00500 
00501   // initialize decoder class
00502   m_cDecLib.init(
00503 #if JVET_J0090_MEMORY_BANDWITH_MEASURE
00504     m_cacheCfgFile
00505 #endif
00506   );
00507   m_cDecLib.setDecodedPictureHashSEIEnabled(m_decodedPictureHashSEIEnabled);
00508 
00509 
00510   if (!m_outputDecodedSEIMessagesFilename.empty())
00511   {
00512     std::ostream &os=m_seiMessageFileStream.is_open() ? m_seiMessageFileStream : std::cout;
00513     m_cDecLib.setDecodedSEIMessageOutputStream(&os);
00514   }
00515 #if JVET_S0257_DUMP_360SEI_MESSAGE
00516   if (!m_outputDecoded360SEIMessagesFilename.empty())
00517   {
00518     m_cDecLib.setDecoded360SEIMessageFileName(m_outputDecoded360SEIMessagesFilename);
00519   }
00520 #endif
00521   m_cDecLib.m_targetSubPicIdx = this->m_targetSubPicIdx;
00522   m_cDecLib.initScalingList();
00523 }
