00543 void DecAppMem::xWriteOutput( PicList* pcListPic, uint32_t tId )
00544 {
00545   if (pcListPic->empty())
00546   {
00547     return;
00548   }
00549 
00550   PicList::iterator iterPic   = pcListPic->begin();
00551   int numPicsNotYetDisplayed = 0;
00552   int dpbFullness = 0;
00553   const SPS* activeSPS = (pcListPic->front()->cs->sps);
00554   uint32_t maxNumReorderPicsHighestTid;
00555   uint32_t maxDecPicBufferingHighestTid;
00556   uint32_t maxNrSublayers = activeSPS->getMaxTLayers();
00557 
00558   const VPS* referredVPS = pcListPic->front()->cs->vps;
00559   const int temporalId = ( m_iMaxTemporalLayer == -1 || m_iMaxTemporalLayer >= maxNrSublayers ) ? maxNrSublayers - 1 : m_iMaxTemporalLayer;
00560 
00561   if( referredVPS == nullptr || referredVPS->m_numLayersInOls[referredVPS->m_targetOlsIdx] == 1 )
00562   {
00563     maxNumReorderPicsHighestTid = activeSPS->getMaxNumReorderPics( temporalId );
00564     maxDecPicBufferingHighestTid = activeSPS->getMaxDecPicBuffering( temporalId );
00565   }
00566   else
00567   {
00568     maxNumReorderPicsHighestTid = referredVPS->getMaxNumReorderPics( temporalId );
00569     maxDecPicBufferingHighestTid = referredVPS->getMaxDecPicBuffering( temporalId );
00570   }
00571 
00572   while (iterPic != pcListPic->end())
00573   {
00574     Picture* pcPic = *(iterPic);
00575     if(pcPic->neededForOutput && pcPic->getPOC() > m_iPOCLastDisplay)
00576     {
00577        numPicsNotYetDisplayed++;
00578       dpbFullness++;
00579     }
00580     else if(pcPic->referenced)
00581     {
00582       dpbFullness++;
00583     }
00584     iterPic++;
00585   }
00586 
00587   iterPic = pcListPic->begin();
00588 
00589   if (numPicsNotYetDisplayed>2)
00590   {
00591     iterPic++;
00592   }
00593 
00594   Picture* pcPic = *(iterPic);
00595   if( numPicsNotYetDisplayed>2 && pcPic->fieldPic ) //Field Decoding
00596   {
00597     PicList::iterator endPic   = pcListPic->end();
00598     endPic--;
00599     iterPic   = pcListPic->begin();
00600     while (iterPic != endPic)
00601     {
00602       Picture* pcPicTop = *(iterPic);
00603       iterPic++;
00604       Picture* pcPicBottom = *(iterPic);
00605 
00606       if ( pcPicTop->neededForOutput && pcPicBottom->neededForOutput &&
00607           (numPicsNotYetDisplayed >  maxNumReorderPicsHighestTid || dpbFullness > maxDecPicBufferingHighestTid) &&
00608           (!(pcPicTop->getPOC()%2) && pcPicBottom->getPOC() == pcPicTop->getPOC()+1) &&
00609           (pcPicTop->getPOC() == m_iPOCLastDisplay+1 || m_iPOCLastDisplay < 0))
00610       {
00611         // write to file
00612         numPicsNotYetDisplayed = numPicsNotYetDisplayed-2;
00613         if ( !m_reconFileName.empty() )
00614         {
00615           const Window &conf = pcPicTop->cs->pps->getConformanceWindow();
00616           const bool isTff = pcPicTop->topField;
00617 
00618           bool display = true;
00619 
00620           if (display)
00621           {
00622             m_cVideoIOYuvReconFile[pcPicTop->layerId].write( pcPicTop->getRecoBuf(), pcPicBottom->getRecoBuf(),
00623                                           m_outputColourSpaceConvert,
00624                                           false, // TODO: m_packedYUVMode,
00625                                           conf.getWindowLeftOffset() * SPS::getWinUnitX( pcPicTop->cs->sps->getChromaFormatIdc() ),
00626                                           conf.getWindowRightOffset() * SPS::getWinUnitX( pcPicTop->cs->sps->getChromaFormatIdc() ),
00627                                           conf.getWindowTopOffset() * SPS::getWinUnitY( pcPicTop->cs->sps->getChromaFormatIdc() ),
00628                                           conf.getWindowBottomOffset() * SPS::getWinUnitY( pcPicTop->cs->sps->getChromaFormatIdc() ),
00629                                           NUM_CHROMA_FORMAT, isTff );
00630           }
00631         }
00632         writeLineToOutputLog(pcPicTop);
00633         writeLineToOutputLog(pcPicBottom);
00634 
00635         // update POC of display order
00636         m_iPOCLastDisplay = pcPicBottom->getPOC();
00637 
00638         // erase non-referenced picture in the reference picture list after display
00639         if ( ! pcPicTop->referenced && pcPicTop->reconstructed )
00640         {
00641           pcPicTop->reconstructed = false;
00642         }
00643         if ( ! pcPicBottom->referenced && pcPicBottom->reconstructed )
00644         {
00645           pcPicBottom->reconstructed = false;
00646         }
00647         pcPicTop->neededForOutput = false;
00648         pcPicBottom->neededForOutput = false;
00649       }
00650     }
00651   }
00652   else if( !pcPic->fieldPic ) //Frame Decoding
00653   {
00654     iterPic = pcListPic->begin();
00655 
00656     while (iterPic != pcListPic->end())
00657     {
00658       pcPic = *(iterPic);
00659 
00660       if(pcPic->neededForOutput && pcPic->getPOC() > m_iPOCLastDisplay &&
00661         (numPicsNotYetDisplayed >  maxNumReorderPicsHighestTid || dpbFullness > maxDecPicBufferingHighestTid))
00662       {
00663         // write to file
00664         numPicsNotYetDisplayed--;
00665         if (!pcPic->referenced)
00666         {
00667           dpbFullness--;
00668         }
00669 
00670 
00671         if (!m_reconFileName.empty())
00672         {
00673           const Window &conf = pcPic->getConformanceWindow();
00674           const SPS* sps = pcPic->cs->sps;
00675           ChromaFormat chromaFormatIDC = sps->getChromaFormatIdc();
00676           if( m_upscaledOutput )
00677           {
00678             m_cVideoIOYuvReconFile[pcPic->layerId].writeUpscaledPicture( *sps, *pcPic->cs->pps, pcPic->getRecoBuf(), m_outputColourSpaceConvert, m_packedYUVMode, m_upscaledOutput, NUM_CHROMA_FORMAT, m_bClipOutputVideoToRec709Range );
00679           }
00680           else
00681           {
00682             m_cVideoIOYuvReconFile[pcPic->layerId].write( pcPic->getRecoBuf().get( COMPONENT_Y ).width, pcPic->getRecoBuf().get( COMPONENT_Y ).height, pcPic->getRecoBuf(),
00683                                         m_outputColourSpaceConvert,
00684                                         m_packedYUVMode,
00685                                         conf.getWindowLeftOffset() * SPS::getWinUnitX( chromaFormatIDC ),
00686                                         conf.getWindowRightOffset() * SPS::getWinUnitX( chromaFormatIDC ),
00687                                         conf.getWindowTopOffset() * SPS::getWinUnitY( chromaFormatIDC ),
00688                                         conf.getWindowBottomOffset() * SPS::getWinUnitY( chromaFormatIDC ),
00689                                         NUM_CHROMA_FORMAT, m_bClipOutputVideoToRec709Range );
00690             }
00691         }
00692         writeLineToOutputLog(pcPic);
00693 
00694         // update POC of display order
00695         m_iPOCLastDisplay = pcPic->getPOC();
00696 
00697         // erase non-referenced picture in the reference picture list after display
00698         if (!pcPic->referenced && pcPic->reconstructed)
00699         {
00700           pcPic->reconstructed = false;
00701         }
00702         pcPic->neededForOutput = false;
00703       }
00704 
00705       iterPic++;
00706     }
00707   }
00708 }
00709 
00712 #if JVET_S0078_NOOUTPUTPRIORPICFLAG
00713 void DecAppMem::xFlushOutput( PicList *pcListPic, const int layerId, bool noOutputOfPriorPicsFlag)
00714 #else
00715 void DecAppMem::xFlushOutput( PicList* pcListPic, const int layerId )
00716 #endif
00717 {
00718   if(!pcListPic || pcListPic->empty())
00719   {
00720     return;
00721   }
00722   PicList::iterator iterPic   = pcListPic->begin();
00723 
00724   iterPic   = pcListPic->begin();
00725   Picture* pcPic = *(iterPic);
00726 
00727   if (pcPic->fieldPic ) //Field Decoding
00728   {
00729     PicList::iterator endPic   = pcListPic->end();
00730     endPic--;
00731     Picture *pcPicTop, *pcPicBottom = NULL;
00732     while (iterPic != endPic)
00733     {
00734       pcPicTop = *(iterPic);
00735       iterPic++;
00736       pcPicBottom = *(iterPic);
00737 
00738       if( pcPicTop->layerId != layerId && layerId != NOT_VALID )
00739       {
00740         continue;
00741       }
00742 
00743       if ( pcPicTop->neededForOutput && pcPicBottom->neededForOutput && !(pcPicTop->getPOC()%2) && (pcPicBottom->getPOC() == pcPicTop->getPOC()+1) )
00744       {
00745 #if JVET_S0078_NOOUTPUTPRIORPICFLAG
00746         if (!noOutputOfPriorPicsFlag)
00747         {
00748 #endif
00749           // write to file
00750           if ( !m_reconFileName.empty() )
00751           {
00752             const Window &conf = pcPicTop->cs->pps->getConformanceWindow();
00753             const bool    isTff   = pcPicTop->topField;
00754 
00755             m_cVideoIOYuvReconFile[pcPicTop->layerId].write( pcPicTop->getRecoBuf(), pcPicBottom->getRecoBuf(),
00756                                         m_outputColourSpaceConvert,
00757                                         false, // TODO: m_packedYUVMode,
00758                                         conf.getWindowLeftOffset() * SPS::getWinUnitX( pcPicTop->cs->sps->getChromaFormatIdc() ),
00759                                         conf.getWindowRightOffset() * SPS::getWinUnitX( pcPicTop->cs->sps->getChromaFormatIdc() ),
00760                                         conf.getWindowTopOffset() * SPS::getWinUnitY( pcPicTop->cs->sps->getChromaFormatIdc() ),
00761                                         conf.getWindowBottomOffset() * SPS::getWinUnitY( pcPicTop->cs->sps->getChromaFormatIdc() ),
00762                                         NUM_CHROMA_FORMAT, isTff );
00763           }
00764           writeLineToOutputLog(pcPicTop);
00765           writeLineToOutputLog(pcPicBottom);
00766 #if JVET_S0078_NOOUTPUTPRIORPICFLAG
00767         }
00768 #endif
00769         // update POC of display order
00770         m_iPOCLastDisplay = pcPicBottom->getPOC();
00771 
00772         // erase non-referenced picture in the reference picture list after display
00773         if( ! pcPicTop->referenced && pcPicTop->reconstructed )
00774         {
00775           pcPicTop->reconstructed = false;
00776         }
00777         if( ! pcPicBottom->referenced && pcPicBottom->reconstructed )
00778         {
00779           pcPicBottom->reconstructed = false;
00780         }
00781         pcPicTop->neededForOutput = false;
00782         pcPicBottom->neededForOutput = false;
00783 
00784         if(pcPicTop)
00785         {
00786           pcPicTop->destroy();
00787           delete pcPicTop;
00788           pcPicTop = NULL;
00789         }
00790       }
00791     }
00792     if(pcPicBottom)
00793     {
00794       pcPicBottom->destroy();
00795       delete pcPicBottom;
00796       pcPicBottom = NULL;
00797     }
00798   }
00799   else //Frame decoding
00800   {
00801     while (iterPic != pcListPic->end())
00802     {
00803       pcPic = *(iterPic);
00804 
00805       if( pcPic->layerId != layerId && layerId != NOT_VALID )
00806       {
00807         iterPic++;
00808         continue;
00809       }
00810 
00811       if (pcPic->neededForOutput)
00812       {
00813 #if JVET_S0078_NOOUTPUTPRIORPICFLAG
00814         if (!noOutputOfPriorPicsFlag)
00815         {
00816 #endif
00817           // write to file
00818           if (!m_reconFileName.empty())
00819           {
00820             const Window &conf = pcPic->getConformanceWindow();
00821             const SPS* sps = pcPic->cs->sps;
00822             ChromaFormat chromaFormatIDC = sps->getChromaFormatIdc();
00823             if( m_upscaledOutput )
00824             {
00825               m_cVideoIOYuvReconFile[pcPic->layerId].writeUpscaledPicture( *sps, *pcPic->cs->pps, pcPic->getRecoBuf(), m_outputColourSpaceConvert, m_packedYUVMode, m_upscaledOutput, NUM_CHROMA_FORMAT, m_bClipOutputVideoToRec709Range );
00826             }
00827             else
00828             {
00829               m_cVideoIOYuvReconFile[pcPic->layerId].write( pcPic->getRecoBuf().get( COMPONENT_Y ).width, pcPic->getRecoBuf().get( COMPONENT_Y ).height, pcPic->getRecoBuf(),
00830                                         m_outputColourSpaceConvert,
00831                                         m_packedYUVMode,
00832                                         conf.getWindowLeftOffset() * SPS::getWinUnitX( chromaFormatIDC ),
00833                                         conf.getWindowRightOffset() * SPS::getWinUnitX( chromaFormatIDC ),
00834                                         conf.getWindowTopOffset() * SPS::getWinUnitY( chromaFormatIDC ),
00835                                         conf.getWindowBottomOffset() * SPS::getWinUnitY( chromaFormatIDC ),
00836                                         NUM_CHROMA_FORMAT, m_bClipOutputVideoToRec709Range );
00837               }
00838           }
00839           writeLineToOutputLog(pcPic);
00840 #if JVET_S0078_NOOUTPUTPRIORPICFLAG
00841         }
00842 #endif
00843         // update POC of display order
00844         m_iPOCLastDisplay = pcPic->getPOC();
00845 
00846         // erase non-referenced picture in the reference picture list after display
00847         if (!pcPic->referenced && pcPic->reconstructed)
00848         {
00849           pcPic->reconstructed = false;
00850         }
00851         pcPic->neededForOutput = false;
00852       }
00853       if(pcPic != NULL)
00854       {
00855         pcPic->destroy();
00856         delete pcPic;
00857         pcPic = NULL;
00858         *iterPic = nullptr;
00859       }
00860       iterPic++;
00861     }
00862   }
00863 
00864   if( layerId != NOT_VALID )
00865   {
00866     pcListPic->remove_if([](Picture* p) { return p == nullptr; });
00867   }
00868   else
00869   pcListPic->clear();
00870   m_iPOCLastDisplay = -MAX_INT;
00871 }
