00875 bool DecAppMem::xIsNaluWithinTargetDecLayerIdSet( const InputNALUnit* nalu ) const
00876 {
00877   if( !m_targetDecLayerIdSet.size() ) // By default, the set is empty, meaning all LayerIds are allowed
00878   {
00879     return true;
00880   }
00881 
00882   return std::find( m_targetDecLayerIdSet.begin(), m_targetDecLayerIdSet.end(), nalu->m_nuhLayerId ) != m_targetDecLayerIdSet.end();
00883 }
00884 
00887 bool DecAppMem::xIsNaluWithinTargetOutputLayerIdSet( const InputNALUnit* nalu ) const
00888 {
00889   if( !m_targetOutputLayerIdSet.size() ) // By default, the set is empty, meaning all LayerIds are allowed
00890   {
00891     return true;
00892   }
00893 
00894   return std::find( m_targetOutputLayerIdSet.begin(), m_targetOutputLayerIdSet.end(), nalu->m_nuhLayerId ) != m_targetOutputLayerIdSet.end();
00895 }
